const input = { ...$json };
if (input.company !== undefined && input.company_name === undefined) {
  input.company_name = input.company;
}
delete input.company;
return { json: input };

const statusCode = Number($json.statusCode ?? 0);
const body = $json.body ?? {};
const requestId = $json.headers?.['x-request-id'] ?? body.detail?.request_id ?? null;
let routeKey = 'api_error';
if (statusCode >= 200 && statusCode < 300) {
  if (body.validation_result?.is_valid !== true) {
    routeKey = 'invalid';
  } else {
    const level = body.analysis_result?.decision?.intent_level;
    if (level === 'High') routeKey = 'high';
    else if (level === 'Medium') routeKey = 'medium';
    else if (level === 'Low') routeKey = 'low';
  }
}
return { json: { route_key: routeKey, request_id: requestId, transport_status: statusCode, result: body } };

const body = $json.result;
const analysis = body.analysis_result;
return { json: { route: 'high', request_id: $json.request_id, lead_id: body.cleaned_lead.lead_id, external_lead_id: body.cleaned_lead.external_lead_id, email: body.cleaned_lead.email, company_name: body.cleaned_lead.company_name, is_valid: true, error_codes: [], intent_level: analysis.decision.intent_level, lead_score: analysis.decision.lead_score, disposition: analysis.decision.disposition, policy_version: analysis.decision.policy_version, analysis_method: analysis.metadata.analysis_method, sources: body.sources, crm_status: 'To Review', priority: 'High', next_step: 'Review immediately and prepare a personalized follow-up.' } };

